// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) (http.Handler, error) {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) (http.Handler, error) {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) (http.Handler, error) {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) (http.Handler, error) {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	schemaRegistry := NewSchemaRegistry()
	if err := schemaRegistry.Register("CreateBeer", CreateBeerJSONRequestBodySchema); err != nil {
		return nil, err
	}
	if err := schemaRegistry.Register("UpdateBeer", UpdateBeerJSONRequestBodySchema); err != nil {
		return nil, err
	}
	if err := schemaRegistry.Register("ReplaceBeer", ReplaceBeerJSONRequestBodySchema); err != nil {
		return nil, err
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
		SchemaRegistry:     schemaRegistry,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/beers", wrapper.ListBeers)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/beers", wrapper.CreateBeer)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/beers/{beerId}", wrapper.DeleteBeer)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/beers/{beerId}", wrapper.GetBeer)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/beers/{beerId}", wrapper.UpdateBeer)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/beers/{beerId}", wrapper.ReplaceBeer)
	})

	return r, nil
}
